
/* features-v2.js */
(() => {
  async function getJson(url){const r=await fetch(url,{cache:'no-store'});if(!r.ok)throw new Error(`Failed ${url}`);return r.json()}
  function ensureStyle(href,key){if(document.querySelector(`link[data-style="${key}"]`))return;const l=document.createElement('link');l.rel='stylesheet';l.href=href;l.dataset.style=key;document.head.appendChild(l)}
  function ensureUiStyles(){ensureStyle('features-v3.css?v=20260823j','brief-v3');ensureStyle('ux-v8.css?v=20260823j','ux-v8')}
  function updatedLabel(v){const d=v?new Date(v):null;if(!d||Number.isNaN(d.valueOf()))return'Updated daily';return`Updated ${new Intl.DateTimeFormat('en-CA',{hour:'numeric',minute:'2-digit'}).format(d)}`}
  function sourceAction(i){return i.mediaType==='video'?`Watch${i.source?` on ${i.source}`:''}`:(i.source||'Source')}
  function whyBlock(i){return Number(i.importance||0)>=4&&i.why?`<p class="brief-why"><strong>Why it matters:</strong> ${i.why}</p>`:''}
  function storyVisual(i,c='brief-story-image'){return i.image?`<img class="${c}" src="${i.image}" alt="" loading="lazy">`:''}

  async function injectDailyBrief(){const hero=document.querySelector('.election-hero');if(!hero||document.querySelector('.daily-brief'))return;try{const data=await getJson('data/daily-brief.json'),items=(data.items||[]).slice(0,3);if(!items.length)return;const lead=items[0],others=items.slice(1),visual=storyVisual(lead),s=document.createElement('details');s.className='daily-brief';s.id='daily-brief';s.innerHTML=`<summary class="brief-toggle"><span><span class="brief-toggle-main"><span class="brief-toggle-title">Burlington in 30 seconds</span><span class="brief-live-dot" aria-hidden="true"></span><span class="brief-toggle-updated">${updatedLabel(data.updated)}</span></span><span class="brief-toggle-sub">The biggest changes in Burlington politics.</span></span><span class="brief-open-label">Open</span></summary><div class="brief-panel"><article class="brief-feature ${visual?'has-image':'no-image'}">${visual?`<div class="brief-feature-visual">${visual}</div>`:''}<div class="brief-feature-copy"><span class="brief-tag">${lead.tag||'Update'}</span><h3><a href="${lead.url}" target="_blank" rel="noopener">${lead.headline}</a></h3><p class="brief-summary">${lead.summary}</p>${whyBlock(lead)}<a class="brief-source" href="${lead.url}" target="_blank" rel="noopener">${sourceAction(lead)}</a></div></article><div class="brief-more">${others.map(i=>{const im=storyVisual(i,'brief-mini-image');return`<article class="brief-mini ${im?'has-image':'no-image'}">${im}<div class="brief-mini-copy"><span class="brief-tag">${i.tag||'Update'}</span><h3><a href="${i.url}" target="_blank" rel="noopener">${i.headline}</a></h3><p>${i.summary}</p>${whyBlock(i)}<a class="brief-source" href="${i.url}" target="_blank" rel="noopener">${sourceAction(i)}</a></div></article>`}).join('')}</div><div class="brief-footer"><a href="updates.html">See all updates →</a></div></div>`;hero.insertAdjacentElement('afterend',s)}catch(e){console.warn('Daily brief unavailable',e)}}

  async function injectBallotQuick(){const matters=document.getElementById('matters');if(!matters||document.querySelector('.ballot-quick'))return;try{const data=await getJson('data/ballot.json'),s=document.createElement('section');s.className='ballot-quick';s.id='your-ballot';s.innerHTML=`<div class="ballot-quick-head"><div><h2>Your ballot</h2><p>Choose your ward to see your councillor race.</p></div><select class="ward-select" id="wardQuick" aria-label="Choose your Burlington ward">${[1,2,3,4,5,6].map(w=>`<option value="${w}">Ward ${w}</option>`).join('')}</select></div><div class="ballot-grid" id="ballotQuickGrid"></div><div class="ballot-actions"><a href="ward.html">What ward am I in? →</a><a href="ballot.html">Full ballot guide →</a></div>`;matters.insertAdjacentElement('beforebegin',s);const sel=s.querySelector('#wardQuick'),g=s.querySelector('#ballotQuickGrid'),render=()=>{const w=data.wards[sel.value];g.innerHTML=`<div class="ballot-block"><small>Mayor</small><b>Citywide</b><div class="ballot-names"><a class="ballot-name" href="election-guide.html#candidates">5 candidates →</a></div></div><div class="ballot-block"><small>Councillor</small><b>Ward ${sel.value}</b><div class="ballot-names"><a class="ballot-name" href="ballot.html?ward=${sel.value}">${w.councillor.length} candidates →</a></div></div><div class="ballot-block ballot-school-mini"><small>School-board trustee</small><b>Optional ballot detail</b><div class="ballot-names"><a class="ballot-name" href="ballot.html?ward=${sel.value}#school-board">View trustee race →</a></div></div>`};sel.addEventListener('change',render);render()}catch(e){console.warn('Ballot quick view unavailable',e)}}

  function fixHeroMap(){const c=document.querySelector('.hero-map-card');if(!c)return;c.querySelector('.hero-map-embed')?.remove();c.querySelector('.map-credit')?.remove();c.classList.add('hero-map-image');c.style.backgroundImage="url('/db00c009-e70d-404d-a8dd-45c6153cff6f.png')";let p=c.querySelector('.hero-place-dot');if(!p){p=document.createElement('span');p.className='hero-place-dot';c.appendChild(p)}p.setAttribute('aria-hidden','true')}
  function polishBrandAndMeta(){document.querySelectorAll('.brand').forEach(b=>{b.classList.add('brand-mark-only');b.innerHTML='<span class="brand-letter" aria-hidden="true">B</span><span class="sr-only">Burlington</span>';b.setAttribute('aria-label','Burlington home')});let i=document.querySelector('link[rel="icon"]');if(!i){i=document.createElement('link');i.rel='icon';document.head.appendChild(i)}i.href='favicon.svg?v=20260823j';const t=document.querySelector('.hero-trust');if(t)t.innerHTML='<span>No endorsements</span><span>Independent</span>'}

  function installDesktopNav(){const inner=document.querySelector('.header-inner'),controls=document.querySelector('.header-controls');if(!inner||!controls||inner.querySelector('.desktop-primary-nav'))return;const n=document.createElement('nav');n.className='desktop-primary-nav';n.setAttribute('aria-label','Quick links');const home=location.pathname==='/'||location.pathname.endsWith('/index.html'),href=h=>home?h:`index.html${h}`;n.innerHTML=`<a href="${href('#candidates')}">Candidates</a><a href="${href('#matters')}">Issues</a><a href="head-to-head.html">Compare</a>`;inner.insertBefore(n,controls);const d=document.querySelector('.menu-panel .menu-primary');if(d){[...d.querySelectorAll('.menu-link')].forEach(a=>{const x=a.textContent.trim().toLowerCase();if(x.startsWith('meet the candidates')||x.startsWith('issues')||x.startsWith('compare'))a.classList.add('menu-core-duplicate');if(x.includes('burlington in 30 seconds'))a.remove()});if(!d.querySelector('a[href="puzzles.html"]'))d.insertAdjacentHTML('beforeend','<a class="menu-link" role="listitem" href="puzzles.html"><span>Puzzles</span><span aria-hidden="true">›</span></a>')}}
  function simplifyFooter(){const f=document.querySelector('.site-legal-footer');if(!f)return;f.innerHTML='<div class="site-legal-footer-inner footer-only-links"><nav class="site-legal-links" aria-label="Site information"><a href="help.html#accessibility">Accessibility</a><a href="terms.html">Terms of use</a><a href="privacy.html">Privacy policy</a><a href="independent.html">Independent</a></nav></div>'}
  function fixLabels(){const t=document.querySelector('#matters h2');if(t)t.textContent='Issues';document.querySelectorAll('#candidateStrip .focus-label').forEach(x=>x.textContent='Overview');document.querySelectorAll('.meaning-detail summary,.plain summary').forEach(s=>{if(/in plain english|what does that mean/i.test(s.textContent))s.textContent='What this means'});const m=document.querySelector('.menu-icon-button');if(m&&!m.dataset.mobileTopBound){m.dataset.mobileTopBound='1';m.addEventListener('click',()=>{const h=document.querySelector('.header');if(h)document.documentElement.style.setProperty('--mobile-menu-top',`${Math.ceil(h.getBoundingClientRect().bottom)}px`)})}}

  function neutralizeProfileCopy(){const p=document.getElementById('profilePanel');if(!p)return;const clean=()=>{document.querySelectorAll('#candidateStrip .focus-label').forEach(x=>x.textContent='Overview');const f=p.querySelector('.profile-box');if(f){[...f.querySelectorAll('li')].find(li=>/official candidate list confirms (he|she|they) (is|are) running for mayor/i.test(li.textContent))?.remove();const h=f.querySelector('h3');if(h&&(/their argument|what we know so far|what they want to do/i.test(h.textContent)))h.textContent=/current priorities will be added|no detailed.*platform/i.test(f.textContent)?'What we know so far':'What they want to do'}const w=document.createTreeWalker(p,NodeFilter.SHOW_TEXT),nodes=[];while(w.nextNode())nodes.push(w.currentNode);nodes.forEach(n=>{const old=n.nodeValue,next=old.replace(/\bHe is\b/g,'They are').replace(/\bhe is\b/g,'they are').replace(/\bShe is\b/g,'They are').replace(/\bshe is\b/g,'they are').replace(/\bHe previously\b/g,'They previously').replace(/\bhe previously\b/g,'they previously').replace(/\bShe previously\b/g,'They previously').replace(/\bshe previously\b/g,'they previously').replace(/\bHis campaign\b/g,'The campaign').replace(/\bhis campaign\b/g,'the campaign').replace(/\bHer campaign\b/g,'The campaign').replace(/\bher campaign\b/g,'the campaign').replace(/\bHis\b/g,'Their').replace(/\bhis\b/g,'their').replace(/\bHer\b/g,'Their').replace(/\bher\b/g,'their');if(next!==old)n.nodeValue=next})};clean();let q=false;new MutationObserver(()=>{if(q)return;q=true;requestAnimationFrame(()=>{q=false;clean()})}).observe(p,{childList:true,subtree:true})}

  async function addCommunityDiscussion(){const panel=document.getElementById('profilePanel'),strip=document.getElementById('candidateStrip');if(!panel||!strip)return;try{const data=await getJson('data/community-discussion.json');let lastName='',queued=false;const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));const render=()=>{const name=strip.querySelector('.candidate-card[aria-pressed="true"] h3')?.textContent.trim();if(!name)return;if(name===lastName&&panel.querySelector('.community-discussion'))return;lastName=name;panel.querySelector('.community-discussion')?.remove();[...panel.querySelectorAll('details')].forEach(d=>{if(/local commenters|local discussion/i.test(d.querySelector('summary')?.textContent||''))d.remove()});const info=data.candidates?.[name];if(!info)return;const items=info.items||[],d=document.createElement('details');d.className='community-discussion';d.innerHTML=`<summary>Local comments checked</summary><p class="community-note">Public comments are not polling or proof. We include substantive points, then check the factual part separately.</p>${items.length?`<div class="community-grid">${items.map(i=>`<article class="community-quote"><div class="community-quote-top"><span class="community-tone">${esc(i.tone)}</span><span class="community-status">${esc(i.status)}</span><span class="community-score">Evidence ${Number(i.evidenceScore||0)}/3</span></div><blockquote>“${esc(i.quote)}”</blockquote><p class="community-check">${esc(i.check)}</p><div class="community-evidence"><a class="community-source" href="${esc(i.url)}" target="_blank" rel="noopener">Original comment ↗</a>${(i.evidence||[]).map(e=>`<a href="${esc(e.url)}" target="_blank" rel="noopener">${esc(e.label)} ↗</a>`).join('')}</div></article>`).join('')}</div>`:`<p class="community-empty">${esc(info.note||'No substantive local comments have been verified yet.')}</p>`}`;panel.appendChild(d)};render();new MutationObserver(()=>{if(queued)return;queued=true;requestAnimationFrame(()=>{queued=false;render()})}).observe(panel,{childList:true,subtree:true})}catch(e){console.warn('Community discussion unavailable',e)}}

  function enhanceHeadToHead(){const grid=document.querySelector('.match-grid'),context=document.getElementById('context'),compare=document.getElementById('compare'),bottom=document.getElementById('bottomStrip');if(!grid||!context||!compare||!bottom)return;document.body.classList.add('h2h-polished');let internal=false,queued=false;const clean=()=>{if(internal)return;internal=true;document.querySelector('.method-link')?.remove();document.querySelectorAll('.person-card .fact').forEach(f=>{if(/question to ask/i.test(f.querySelector('b')?.textContent||''))f.remove()});document.querySelectorAll('.plain summary').forEach(s=>{if(/what does that mean|in plain english/i.test(s.textContent))s.textContent='What this means'});if(!context.querySelector('details')){const h=context.querySelector('h2')?.textContent||'Context',b=context.querySelector('p')?.innerHTML||'';context.innerHTML=`<details class="h2h-context-details"><summary>${h}</summary><div class="h2h-context-body"><p>${b}</p></div></details>`}const pos=[...compare.children],checks=[...bottom.children];[['leftCard',0],['rightCard',1]].forEach(([id,i])=>{const card=document.getElementById(id);if(!card)return;card.querySelector('.h2h-position-slot')?.remove();const slot=document.createElement('div');slot.className='h2h-position-slot';slot.innerHTML='<div class="h2h-section-label">On this issue</div>';if(pos[i])slot.appendChild(pos[i].cloneNode(true));if(checks[i]){const c=checks[i].cloneNode(true),b=c.querySelector('b');if(b)b.textContent='What still needs checking';slot.appendChild(c)}card.appendChild(slot)});requestAnimationFrame(()=>internal=false)};clean();new MutationObserver(()=>{if(internal||queued)return;queued=true;requestAnimationFrame(()=>{queued=false;clean()})}).observe(grid,{childList:true,subtree:true})}

  function eventStatus(start,end){const now=new Date(),s=new Date(start),e=end?new Date(end):null,t=new Date(now.getFullYear(),now.getMonth(),now.getDate(),12),sd=new Date(s.getFullYear(),s.getMonth(),s.getDate(),12),days=Math.round((sd-t)/86400000);if(e&&now>=s&&now<=e)return'Happening now';if(now>(e||s))return'Finished';if(days===0)return'Today';if(days===1)return'Tomorrow';return`In ${days} days`}
  function icsHref(e){const fmt=v=>new Date(v).toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');const s=fmt(e.date),end=fmt(e.end||new Date(new Date(e.date).getTime()+3600000)),text=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Burlington Election Guide//EN','BEGIN:VEVENT',`UID:${s}-${e.title.replace(/\s+/g,'-')}@burlingtonnews.ca`,`DTSTAMP:${fmt(new Date())}`,`DTSTART:${s}`,`DTEND:${end}`,`SUMMARY:${e.title.replace(/,/g,'\\,')}`,`DESCRIPTION:${e.detail.replace(/,/g,'\\,')} ${e.url}`,'END:VEVENT','END:VCALENDAR'].join('\r\n');return'data:text/calendar;charset=utf-8,'+encodeURIComponent(text)}
  async function syncImportantDates(){const s=document.getElementById('dates');if(!s)return;try{const data=await getJson('data/events.json'),g=s.querySelector('.date-grid');if(!g)return;g.classList.add('date-timeline');g.innerHTML=(data.events||[]).map(e=>{const [m,...d]=e.displayDate.split(' '),status=eventStatus(e.date,e.end),critical=Number(e.importance||0)>=5?' is-critical':'',add=e.addToCalendar?`<a class="date-calendar-action" href="${icsHref(e)}" download="election-day.ics">Add to calendar</a>`:'';return`<article class="card date-card date-stop${critical} ${/Finished/i.test(status)?'is-past':''}"><div class="date-stop-top"><div class="date-calendar" aria-hidden="true"><span class="date-calendar-month">${m.toUpperCase().replace('.','')}</span><span class="date-calendar-day">${d.join(' ')}</span></div><span class="date-status">${status}</span></div><div class="date-stop-body"><h3><a class="date-title-link" href="${e.url}" target="_blank" rel="noopener">${e.title}</a></h3><p>${e.detail}</p>${add}</div></article>`}).join('');simplifyDateCountdowns()}catch(e){console.warn('Election events unavailable',e)}}
  function simplifyDateCountdowns(){const c=[...document.querySelectorAll('.date-stop')];if(!c.length)return;const a=c.filter(x=>!/finished/i.test(x.querySelector('.date-status')?.textContent||''));c.forEach(x=>x.classList.remove('countdown-visible'));a[0]?.classList.add('countdown-visible');const e=c.find(x=>/election day/i.test(x.textContent));if(e&&e!==a[0])e.classList.add('countdown-visible')}
  async function injectElectionResults(){try{const d=await getJson('data/election-results.json');if(!d||d.display!==true)return;const a=document.querySelector('.daily-brief')||document.querySelector('.election-hero');if(!a||document.querySelector('.election-results'))return;const rows=(d.mayor||[]).slice(0,5),s=document.createElement('section');s.className='election-results';s.innerHTML=`<div class="results-head"><div><span class="results-live-dot"></span><strong>Election results</strong><small>${d.official?'Official':'Unofficial'} · updated ${updatedLabel(d.updatedAt).replace('Updated ','')}</small></div><a href="${d.sourceUrl}" target="_blank" rel="noopener">City results</a></div>${rows.length?`<div class="results-list">${rows.map(r=>`<div class="result-row"><span>${r.name}</span><strong>${Number(r.votes||0).toLocaleString('en-CA')}</strong>${r.percent!=null?`<small>${r.percent}%</small>`:''}</div>`).join('')}</div>`:'<p class="results-waiting">Polls are closed. Waiting for the City of Burlington to publish result data.</p>'}`;a.insertAdjacentElement('afterend',s)}catch(_){}}
  function injectHomeExtras(){const d=document.getElementById('dates');if(!d||document.querySelector('.home-extras'))return;const e=document.createElement('section');e.className='home-extras';e.innerHTML=`<div class="home-extra-grid"><a class="home-extra-card puzzles-card" href="puzzles.html"><span class="home-extra-icon" aria-hidden="true">✦</span><div><small>Play</small><h2>Burlington puzzles</h2><p>Quick local trivia and visual challenges.</p></div><span aria-hidden="true">→</span></a><a class="home-extra-card beginner-card" href="elections-for-beginners.html"><span class="home-extra-icon" aria-hidden="true">?</span><div><small>Start here</small><h2>Elections for beginners</h2><p>What each local office controls and how city decisions get made.</p></div><span aria-hidden="true">→</span></a></div>`;d.insertAdjacentElement('afterend',e)}

  function init(){ensureUiStyles();polishBrandAndMeta();fixHeroMap();fixLabels();neutralizeProfileCopy();enhanceHeadToHead();injectDailyBrief();injectBallotQuick();injectElectionResults();addCommunityDiscussion();setTimeout(()=>{installDesktopNav();syncImportantDates();simplifyFooter();polishBrandAndMeta();injectHomeExtras();enhanceHeadToHead();fixLabels()},220)}
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();
})();

/* news-v1.js */
(() => {
  const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
  const fetchJson=async url=>{const r=await fetch(url,{cache:'no-store'});if(!r.ok)throw new Error(url);return r.json()};
  const home=()=>location.pathname==='/'||location.pathname.endsWith('/index.html');
  const brandMarkup='<span class="news-brand-mark" aria-hidden="true"></span><span class="news-brand-copy"><strong>Burlington News</strong><small>Burlington, Ontario</small></span>';

  function restoreBrand(){
    document.querySelectorAll('.brand').forEach(b=>{if(!b.classList.contains('news-brand')||!b.querySelector('.news-brand-copy')){b.className='brand news-brand';b.href='index.html';b.innerHTML=brandMarkup;b.setAttribute('aria-label','Burlington News home')}});
    let icon=document.querySelector('link[rel="icon"]');if(!icon){icon=document.createElement('link');icon.rel='icon';document.head.appendChild(icon)}icon.href='favicon.svg?v=20260824a';
    const path=location.pathname.replace(/\/$/,'');
    const titles={
      '':'Burlington News | 2026 Municipal Election Guide','/index.html':'Burlington News | 2026 Municipal Election Guide',
      '/head-to-head.html':'Compare Burlington Mayor Candidates | Burlington News','/ballot.html':'Your Burlington Ballot | Burlington News','/ward.html':'What Ward Am I In? | Burlington News',
      '/updates.html':'Burlington in 30 Seconds | Burlington News','/explore.html':'Explore Burlington | Burlington News','/promises.html':'Promises & Records | Burlington News','/puzzles.html':'Burlington Puzzles | Burlington News','/elections-for-beginners.html':'Elections for Beginners | Burlington News',
      '/methodology.html':'Sources & Methodology | Burlington News','/help.html':'Help & Feedback | Burlington News','/privacy.html':'Privacy Policy | Burlington News','/terms.html':'Terms of Use | Burlington News','/independent.html':'Independent | Burlington News','/feedback':'Give feedback | Burlington News'
    };
    if(titles[path])document.title=titles[path];else if(/Burlington Election Guide/i.test(document.title))document.title=document.title.replace(/Burlington Election Guide/ig,'Burlington News');
  }
  function restoreBanner(){let b=document.querySelector('.banner'),h=document.querySelector('.header');if(!b&&h){b=document.createElement('div');b.className='banner';h.before(b)}if(b)b.innerHTML='<div class="wrap"><strong>2026 Election Guide</strong>&nbsp;&nbsp;·&nbsp;&nbsp;Voting starts Oct. 14&nbsp;&nbsp;·&nbsp;&nbsp;Election Day Oct. 26</div>'}
  function restoreFooter(){
    let f=document.querySelector('.site-legal-footer');if(!f){f=document.createElement('footer');f.className='site-legal-footer';document.body.appendChild(f)}
    if(f.dataset.newsFooter==='2')return;f.dataset.newsFooter='2';
    f.innerHTML='<div class="site-legal-footer-inner"><div class="footer-news-brand"><span class="news-brand-mark" aria-hidden="true"></span><div><strong>Burlington News</strong><p>Independent Burlington civic news and a plain-language 2026 municipal election guide.</p></div></div><nav class="site-legal-links" aria-label="Burlington News sections"><a href="updates.html">News</a><a href="election-guide.html#candidates">Candidates</a><a href="ballot.html">Your ballot</a><a href="elections-for-beginners.html">Election 101</a><a href="puzzles.html">Puzzles</a><a href="methodology.html">Sources & methodology</a><a href="help.html#accessibility">Accessibility</a><a href="independent.html">About / Independent</a><a href="/feedback/">Give feedback</a><a href="terms.html">Terms</a><a href="privacy.html">Privacy</a></nav></div>';
  }

  const isLocalStory=i=>{
    const hay=`${i.title||i.headline||''} ${i.description||i.summary||''} ${i.url||''} ${i.source||''}`.toLowerCase();
    if(/city of burlington|burlingtontoday|focus burlington|burlington election/.test((i.source||'').toLowerCase()))return true;
    return /\bburlington\b|appleby|aldershot|brant street|ward [1-6]|halton region|burloak/.test(hay);
  };
  const normalizedStory=i=>({date:(i.published||i.date||'').slice(0,10),tag:i.tag||'Burlington',headline:i.headline||i.title||'Burlington update',summary:i.summary||i.description||i.headline||i.title||'',why:i.why||'',importance:Number(i.importance||0),url:i.url||'#',image:i.image||''});
  async function getLocalStories(limit=8){
    let items=[];
    try{const monitor=await fetchJson('data/source-monitor.json');items=(monitor.items||[]).filter(isLocalStory).map(normalizedStory)}catch(_){}
    if(items.length<3){try{const brief=await fetchJson('data/daily-brief.json');items.push(...(brief.items||[]).filter(isLocalStory).map(normalizedStory))}catch(_){} }
    const seen=new Set();return items.filter(i=>{const key=i.url||i.headline;if(!key||seen.has(key))return false;seen.add(key);return true}).slice(0,limit);
  }
  function integratedSummary(item){let text=item.summary||'';if(item.importance>=5&&item.why){const w=item.why.trim();if(w&&!text.toLowerCase().includes(w.toLowerCase()))text=`${text.replace(/[.]?$/,'')}. ${w}`}return text}
  function storyCard(item){return `<a class="news-story-card" href="${esc(item.url)}" target="_blank" rel="noopener"><div class="news-story-media">${item.image?`<img src="${esc(item.image)}" alt="" loading="lazy">`:`<div class="news-story-fallback" aria-hidden="true">B</div>`}</div><div class="news-story-body"><span class="news-story-tag">${esc(item.tag)}</span><h3>${esc(item.headline)}</h3><p>${esc(integratedSummary(item))}</p></div></a>`}

  async function rebuildHomeBrief(){
    if(!home())return;const old=document.querySelector('.daily-brief');if(!old)return;
    const items=(await getLocalStories(6)).slice(0,3);if(!items.length)return;
    const section=document.createElement('section');section.className='daily-brief news-brief';section.id='daily-brief';section.innerHTML=`<div class="news-brief-head"><div><h2>Latest in Burlington</h2><p>New local stories and source-linked updates.</p></div><a href="updates.html">All news →</a></div><div class="news-brief-grid">${items.map(storyCard).join('')}</div>`;old.replaceWith(section);
  }

  async function rebuildUpdates(){
    const out=document.getElementById('updatesList');if(!out)return;
    const items=await getLocalStories(12);if(!items.length)return;const top=items.slice(0,3),newest=items.slice(3);
    out.className='news-page-feed';out.innerHTML=`<section class="updates-top"><div class="section-rule"><h2>Top stories</h2><small>What to know now</small></div><div class="news-brief-grid">${top.map(storyCard).join('')}</div></section>${newest.length?`<section class="updates-newest"><div class="section-rule"><h2>Newest</h2><small>Latest updates</small></div><div class="newest-list">${newest.map(i=>`<a class="newest-row" href="${esc(i.url)}" target="_blank" rel="noopener"><span><small>${esc(i.tag)}</small><strong>${esc(i.headline)}</strong><em>${esc(integratedSummary(i))}</em></span><span aria-hidden="true">→</span></a>`).join('')}</div></section>`:''}`;
    document.querySelector('.updates-page .content-lead')?.replaceChildren(document.createTextNode('Local government, elections, development, transit and decisions that affect Burlington.'));
  }

  function rebuildDates(){
    const grid=document.querySelector('#dates .date-grid');if(!grid)return;
    [...grid.querySelectorAll('.date-stop')].forEach(card=>{
      if(card.tagName==='A'){card.querySelector('.date-calendar-action')?.remove();card.querySelector('.date-source')?.remove();return}
      const titleLink=card.querySelector('.date-title-link'),href=titleLink?.getAttribute('href');if(!href)return;
      if(titleLink){const h=titleLink.closest('h3');if(h)h.textContent=titleLink.textContent}
      card.querySelector('.date-calendar-action')?.remove();card.querySelector('.date-source')?.remove();
      const a=document.createElement('a');a.className=card.className;a.href=href;a.target='_blank';a.rel='noopener';a.setAttribute('aria-label',`${card.querySelector('h3')?.textContent||'Election date'} — open details`);a.innerHTML=card.innerHTML;card.replaceWith(a);
    });
  }
  function replacePartner(){const card=document.querySelector('.home-extra-card.partner-card');if(!card)return;card.className='home-extra-card beginner-card';card.href='elections-for-beginners.html';card.innerHTML='<span class="home-extra-icon" aria-hidden="true">?</span><div><small>Start here</small><h2>Elections for beginners</h2><p>What a municipal election is, what each job controls and how a city decision actually gets made.</p></div><span aria-hidden="true">→</span>'}
  function cleanCandidateLabels(){document.querySelectorAll('#candidateStrip .focus-label').forEach(x=>x.textContent='Overview')}
  function watchCandidateLabels(){const strip=document.getElementById('candidateStrip');if(!strip||strip.dataset.newsLabelWatch)return;strip.dataset.newsLabelWatch='1';new MutationObserver(()=>cleanCandidateLabels()).observe(strip,{childList:true,subtree:true,characterData:true})}

  async function runDynamic(){restoreBrand();restoreBanner();restoreFooter();cleanCandidateLabels();watchCandidateLabels();replacePartner();rebuildDates();try{await rebuildHomeBrief()}catch(e){console.warn('Local brief unavailable',e)}try{await rebuildUpdates()}catch(e){console.warn('News feed unavailable',e)}restoreBrand();restoreFooter()}
  const schedule=()=>{runDynamic();setTimeout(runDynamic,350);setTimeout(runDynamic,1100)};
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',schedule,{once:true});else schedule();
})();

/* news-v2.js */
(() => {
  const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
  const home=()=>location.pathname==='/'||location.pathname.endsWith('/index.html');
  const dateText=()=>new Intl.DateTimeFormat('en-CA',{weekday:'long',month:'long',day:'numeric',year:'numeric'}).format(new Date());
  const evidenceLabel=item=>{
    const status=String(item.status||'').toLowerCase(),score=Number(item.evidenceScore||0);
    if(/personal experience|assessment|opinion/.test(status))return['Personal experience','evidence-opinion'];
    if(/unsupported|not verified|no reliable/.test(status)||score===0)return['Not verified','evidence-unverified'];
    if(/partly|incomplete|motive/.test(status)||score===1||score===2)return['Partly verified','evidence-partly'];
    return['Verified','evidence-verified'];
  };

  async function stories(){
    try{const r=await fetch('data/source-monitor.json',{cache:'no-store'}),d=await r.json();return (d.items||[]).filter(x=>x.url&&x.headline&& !/^(List of Candidates|For Candidates|Candidate Financials|Candidate News and Updates)$/i.test(x.headline)).slice(0,3)}catch(_){return[]}
  }
  const media=item=>item?.image?`<img src="${esc(item.image)}" alt="" loading="eager">`:'<span class="publication-media-mark" aria-hidden="true">B</span>';
  async function buildPublicationHome(){
    if(!home()||document.querySelector('.publication-home'))return;
    const main=document.getElementById('main'),items=await stories();if(!main)return;
    const fallback=[
      {tag:'Election',headline:'A clear guide to Burlington’s 2026 election',summary:'Compare candidates, understand the jobs and see the dates that matter.',url:'#election-guide'},
      {tag:'Your ballot',headline:'See every race on your Burlington ballot',summary:'Choose your ward, then review mayor, councillor and trustee candidates.',url:'ballot.html'},
      {tag:'Explainer',headline:'Municipal elections, explained from zero',summary:'What council controls, who you elect and how a decision becomes real.',url:'elections-for-beginners.html'}
    ];
    const lead=items.find(x=>x.image&&/burlington|burloak|transit/i.test(`${x.tag||''} ${x.headline||''}`))||items.find(x=>x.image)||items[0]||fallback[0];
    const side=[
      {tag:'Wildlife',headline:'Why Burlington closes a road for salamanders',summary:'The annual King Road closure protects endangered Jefferson salamanders during their spring migration.',url:'https://www.burlington.ca/en/news/burlington-protecting-endangered-salamanders-by-closing-king-road.aspx',image:'https://static.inaturalist.org/photos/24040203/large.jpeg'},
      {tag:'Bird migration',headline:'The birds passing Burlington that most people never notice',summary:'RBG’s long-running monitoring tracks migratory birds moving through the western Lake Ontario area.',url:'https://www.rbg.ca/app/uploads/Long-Watch-Birds-2015-2024-Summary-Report.pdf?x51525=',image:'https://commons.wikimedia.org/wiki/Special:Redirect/file/Cerulean%20Warbler,%20Rondeau%20Provincial%20Park,%20Ontario,%20Canada.jpg?width=900'},
      {tag:'Fish',headline:'More than 26,000 fish passed through one local fishway',summary:'RBG’s 2025 count shows what is migrating into Cootes Paradise and which native species are recovering.',url:'https://www.rbg.ca/2025-cootes-paradise-fishway-highlights-fish-and-fish-migration/',image:'https://rbg-1c124.kxcdn.com/app/uploads/DSC03362-scaled.jpg?x51525'}
    ];
    const section=document.createElement('section');section.className='publication-home';section.innerHTML=`
      <div class="publication-dateline"><span>${esc(dateText())}</span><nav class="publication-regions" aria-label="Coverage areas"><a href="updates.html">Burlington</a><a href="updates.html#region">Oakville</a><a href="updates.html#region">Hamilton</a><a href="updates.html#region">GTA</a><a href="updates.html#region">Niagara</a><a href="updates.html#world">World</a></nav></div>
      <div class="publication-heading"><h1>Burlington, in one place.</h1><p>Local news, things to do, civic decisions and an election guide that tells you exactly what each choice means.</p></div>
      <div class="publication-lead-grid"><a class="publication-lead" href="${esc(lead.url)}"><div class="publication-lead-media">${media(lead)}</div><span class="publication-tag">${esc(lead.tag||'Burlington')}</span><h2>${esc(lead.headline)}</h2><p>${esc(lead.summary||lead.description||'Open the full update.')}</p></a><div class="publication-side">${side.map(x=>`<a class="publication-side-story" href="${esc(x.url)}" target="_blank" rel="noopener"><div class="publication-side-media">${media(x)}</div><div class="publication-side-copy"><span class="publication-tag">${esc(x.tag||'Burlington')}</span><h3>${esc(x.headline)}</h3><p>${esc(x.summary||x.description||'Open the full update.')}</p></div></a>`).join('')}</div></div>
      <p class="publication-credit">Wildlife images: Jefferson salamander by Jake Scott, CC BY-SA 3.0; Cerulean warbler by Mdf/MPF, CC BY-SA 3.0; Fishway photo via Royal Botanical Gardens.</p>
      <nav class="publication-shortcuts" aria-label="Popular Burlington sections"><a href="updates.html"><small>Newest</small><strong>Today in Burlington</strong></a><a href="explore.html"><small>Do something</small><strong>Explore Burlington</strong></a><a href="#election-guide"><small>2026 vote</small><strong>Election guide</strong></a><a href="puzzles.html"><small>Play</small><strong>Local puzzles</strong></a></nav>`;
    main.prepend(section);
    const hero=document.querySelector('.election-hero');if(hero)hero.id='election-guide';
    const candidates=document.getElementById('candidates');if(candidates&&!document.querySelector('.explore-teaser')){const e=document.createElement('section');e.className='explore-teaser';e.innerHTML='<div><span class="publication-tag">Shuffle your city</span><h2>Find something in Burlington you would never search for.</h2><p>Local oddities, free stops, overlooked history and small challenges. Start with one card and see where it takes you.</p><a href="explore.html">Shuffle the deck →</a></div><div class="explore-stack" aria-hidden="true"><div class="explore-stack-card"></div><div class="explore-stack-card"></div><div class="explore-stack-card"><small>Try this</small><strong>Find the plaque most people walk past.</strong></div></div>';candidates.insertAdjacentElement('beforebegin',e)}
  }
  function fixEvidence(){
    document.querySelectorAll('.community-quote,.ward-community-card').forEach(card=>{const score=card.querySelector('.community-score,.ward-community-score'),status=card.querySelector('.community-status,.ward-community-status');if(!score||score.dataset.fixed)return;const item={status:status?.textContent||'',evidenceScore:Number((score.textContent.match(/\d+/)||[0])[0])},[label,cls]=evidenceLabel(item);score.textContent=label;score.classList.add(cls);score.dataset.fixed='1'});
  }
  function fixCompare(){const head=document.querySelector('main>.head');if(!head||head.dataset.fixed)return;head.dataset.fixed='1';head.className='compare-intro';head.innerHTML='<h1>Settle the debate in seconds.</h1><p>Choose two mayoral candidates and one issue. You’ll see what each person proposes, the shared facts behind the issue and what still needs checking.</p><div class="compare-how"><div><b>1 · Pick two people</b><span>Change either candidate at any time.</span></div><div><b>2 · Choose an issue</b><span>Taxes, housing, traffic and more.</span></div><div><b>3 · Read the difference</b><span>Promises stay separate from verified records.</span></div></div>'}
  function fixBallot(){document.querySelectorAll('.ballot-school-mini b').forEach(label=>{if(/optional ballot detail/i.test(label.textContent))label.textContent='Your trustee race'});document.querySelectorAll('.ward-candidate-card').forEach(card=>{if(card.querySelector('.ward-incumbent'))return;const name=card.dataset.name;if(['Kelvin Galbraith','Paul Sharman','Angelo Bentivegna'].includes(name)){const body=card.querySelector('.ward-candidate-body'),tag=document.createElement('span');tag.className='ward-incumbent';tag.textContent='Current councillor';body?.insertBefore(tag,body.querySelector('.ward-focus-label'))}})}
  function fixPuzzles(){const main=document.querySelector('.puzzles-main');if(!main||main.dataset.copyFixed)return;main.dataset.copyFixed='1';const h=main.querySelector('h1'),lead=main.querySelector('.puzzles-lead');if(h)h.textContent='Puzzles about Burlington.';if(lead)lead.textContent='Visual questions about local places, history and how the city works.';main.querySelectorAll('.section-rule small').forEach(s=>{if(/quick local games/i.test(s.textContent))s.textContent='Popular puzzles'});main.querySelectorAll('.pick-copy h3').forEach(h3=>{if(/how well do you know burlington/i.test(h3.textContent))h3.textContent='Where in Burlington?'})}
  function fixDates(){const section=document.getElementById('dates'),grid=section?.querySelector('.date-grid');if(!section||!grid)return;let detail=section.querySelector('.date-event-detail');if(!detail){detail=document.createElement('article');detail.className='date-event-detail';detail.id='date-event-detail';detail.innerHTML='<span class="date-detail-kicker">Event details</span><h3>Select a date above</h3><p>The full date and time will appear here.</p>';grid.insertAdjacentElement('afterend',detail)}grid.querySelectorAll('.date-stop,.date-card').forEach(card=>{if(card.dataset.detailBound)return;card.dataset.detailBound='1';card.addEventListener('click',e=>{e.preventDefault();const date=card.querySelector('.date-calendar-day,.date')?.textContent?.trim()||'',month=card.querySelector('.date-calendar-month')?.textContent?.trim()||'',title=card.querySelector('h3')?.textContent?.trim()||'Election event',copy=card.querySelector('p')?.textContent?.trim()||'';detail.innerHTML=`<span class="date-detail-kicker">${esc([month,date].filter(Boolean).join(' '))}</span><h3>${esc(title)}</h3><p>${esc(copy)}</p>`;detail.scrollIntoView({behavior:'smooth',block:'center'})})})}
  function tidyFooter(){document.querySelectorAll('.site-legal-links').forEach(nav=>{if(!nav.querySelector('a[href="promises.html"]'))nav.insertAdjacentHTML('afterbegin','<a href="promises.html">Promises & records</a><a href="explore.html">Explore Burlington</a>')})}
  async function enhancePromises(){const shell=document.querySelector('.record-shell'),toolbar=document.querySelector('.record-toolbar');if(!shell||!toolbar||document.querySelector('.polimeter-summary')||shell.dataset.summaryLoading)return;shell.dataset.summaryLoading='1';try{const data=await fetch('data/track-record.json',{cache:'no-store'}).then(r=>r.json()),wrap=document.createElement('section');wrap.className='polimeter-summary';wrap.innerHTML=Object.entries(data.candidates||{}).map(([name,p])=>{const counts={kept:0,progress:0,partial:0,broken:0,other:0};(p.items||[]).forEach(i=>{const s=String(i.status||'').toLowerCase();if(s==='kept')counts.kept++;else if(/advanced|progress/.test(s))counts.progress++;else if(/partial/.test(s))counts.partial++;else if(/broken|not kept/.test(s))counts.broken++;else counts.other++});const total=p.items.length||1,bar=Object.entries(counts).filter(([,n])=>n).map(([k,n])=>`<span class="bar-${k}" style="width:${n/total*100}%"></span>`).join('');return `<article class="promise-overview"><div class="promise-overview-top"><div><span class="promise-place">Burlington · In office</span><small>Current Ward 2 councillor</small><h2>${esc(name)}</h2></div><span class="promise-see">Reviewed record</span></div><div class="promise-metrics"><div><small>Promises tracked</small><strong>${p.items.length}</strong></div><div><small>Last review</small><strong>${esc(data.updated)}</strong></div><div><small>Overall score</small><strong>Not published</strong></div></div><div class="promise-bar" aria-label="Reviewed promise statuses">${bar}</div><div class="promise-legend"><span><i class="bar-kept"></i>Kept ${counts.kept}</span><span><i class="bar-progress"></i>In progress ${counts.progress}</span>${counts.partial?`<span><i class="bar-partial"></i>Partly kept ${counts.partial}</span>`:''}${counts.broken?`<span><i class="bar-broken"></i>Broken ${counts.broken}</span>`:''}</div><p class="promise-sample-note">This describes the ${p.items.length} commitments reviewed so far. It is not a complete record or a candidate grade.</p></article>`}).join('');toolbar.before(wrap)}catch(_){}finally{shell.dataset.summaryLoading=''}}
  function run(){fixCompare();fixBallot();fixEvidence();fixPuzzles();fixDates();tidyFooter();enhancePromises()}
  document.addEventListener('DOMContentLoaded',()=>{buildPublicationHome();run();const body=document.body;if(body)new MutationObserver(()=>run()).observe(body,{childList:true,subtree:true})},{once:true});
})();
